function finish(){const title=CATCH_TITLES[rand(CATCH_TITLES.length)],line=CATCH_LINES[rand(CATCH_LINES.length)];catchTime=0;chase=CHASE_SECONDS;mode='over';save.best=Math.max(save.best,Math.floor(distance));persist();$('controls').hidden=true;$('footer').hidden=false;panel.innerHTML=`<div class="sheet caught"><div class="eyebrow">СЕМЁНЫЧ ДОГНАЛ</div><h2>${title}</h2><p>«${line}»<br>Бутылки уже в кармане. Ещё по одной?</p><div class="stats"><div><strong>${Math.floor(distance)} м</strong><small>ДИСТАНЦИЯ</small></div><div><strong class="lime">+${runBottles}</strong><small>БУТЫЛОК</small></div></div><button class="primary" data-do="start">Ещё забег →</button><div class="row"><button class="secondary" data-do="shop">В приёмку</button><button class="secondary" data-do="home">Главная</button></div></div>`}
