function story(){mode='story';panel.innerHTML='<div class="sheet"><div class="eyebrow">ХРОНИКИ ЗАРЕЧЕНСКА · 01</div><h2>Борис и большое завтра</h2><p>Борис Гайкин когда-то чинил трамваи. Депо закрыли, общежитие продали — и он остался без дома. Теперь его адрес — теплотрасса у седьмого квартала, а мечта — своя маленькая мастерская.</p><p>Тамара из приёмки обещала придержать старый гараж. Плата простая: сдавай стеклотару, копи и не сдавайся. Борис объявил свой личный марафон.</p><p>Но участковый Семёныч увидел, как Борис перемахнул через ограду, и пустился следом. За что именно задерживать — он придумает по дороге.</p><p>Впереди панельные дворы, старый центр с витринами и промзона за сеткой-рабицей; день сменяется ночью, и фонари загораются один за другим. Мешают машины, фургоны, ремонтные барьеры и самокатчики. У каждого есть дела. У Бориса — большое завтра.</p><button class="primary" data-do="home">Понятно, погнали</button></div>'}
function settings(){mode='settings';panel.innerHTML=`<div class="sheet"><h2>Как играть</h2><p>← → / A D — сменить полосу<br>↑ / W / пробел — перепрыгнуть барьер<br>↓ / S — перекат под красной перекладиной<br>Esc / P — пауза. На машины можно запрыгивать, бежать по крыше и прыгать с неё. Самокатчиков обходите.</p><p>Лёгкая ошибка приближает Семёныча. Вторая, пока он рядом, — поимка. Двенадцать секунд чистого бега или пара его падений — отрыв: он тоже спотыкается о мусор и барьеры и влетает в перекладины. Удар в машину, фургон, самокатчика или перекладину завершает забег. Сверху на машины и фургоны можно запрыгивать и бежать по крышам — там тоже бутылки. Щит поглощает удар, но держится ограниченное время.</p><p>Бонусы: магнит, щит, удвоение, кроссовки (высокий прыжок), ранец (полёт над улицей с дорожкой бутылок; вниз — спуститься раньше) и самокат (разгон, принимает на себя один удар). На каждой группе препятствий остаётся свободная полоса.</p><p>Прогресс сохраняется в этом браузере. Для переноса в Telegram или на другое устройство экспортируйте сохранение, затем импортируйте файл там.</p><div class="row"><button class="secondary" data-do="export">Экспорт</button><button class="secondary" data-do="import">Импорт</button></div><p class="hint">iPhone: Safari → «Поделиться» → «На экран Домой». Звук включается после касания.</p><button class="primary" data-do="home">Назад</button></div>`}
panel.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;audioStart();const d=b.dataset;if(d.do){({start,home,shop,story,settings,resume,quit:finish,export:()=>{persist();const blob=new Blob([JSON.stringify(save,null,2)],{type:'application/json'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='pivnoy-ryvok-progress.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},import:()=>$('importFile').click()})[d.do]?.()}if(d.tab){tab=d.tab;shop()}if(d.buy){const k=d.buy,cost=(save[k]+1)*60;if(save[k]<3&&save.wallet>=cost){save.wallet-=cost;save[k]++;persist();sfx('collect');shop()}}if(d.skin!==undefined){const i=Number(d.skin);if(!save.owned.includes(i)&&save.wallet>=skins[i].price){save.wallet-=skins[i].price;save.owned.push(i)}if(save.owned.includes(i)){save.skin=i;loadSkin(i);}persist();shop()}if(d.claim!==undefined){const i=Number(d.claim),goals=[save.total>=100,save.best>=1000,save.runs>=10];if(goals[i]&&!save.claims.includes(i)){save.wallet+=[40,100,70][i];save.claims.push(i);persist();shop()}}});
