let ac=null,noteTime=0,step=0;const melody=[76,0,79,83,81,79,76,74,72,0,76,79,78,74,71,74,76,79,83,86,83,81,79,76,74,71,74,78,79,76,74,0],bass=[40,40,43,43,36,36,38,38];
